<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="theme-color" content="#100e17">
<meta name="description" content="Dune Line is a fictional overnight railway from the desert outpost of Sundown to the neon city of Vesper.">
<link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='7' fill='%23191320'/%3E%3Cpath d='M5 22h22M8 18l5-8 5 8h6' fill='none' stroke='%23ffb295' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E">
<title>Dune Line — The desert after dark</title>
<style>
:root {
  color-scheme: dark;
  --bg: #100e17; --panel: #191522; --ink: #faf1e8; --muted: #beb2c4;
  --peach: #ffb295; --line: #332a3c; --radius: 18px;
  --mono: ui-monospace, "SFMono-Regular", Consolas, monospace;
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body { margin: 0; background: var(--bg); color: var(--ink); font: 16px/1.6 system-ui, sans-serif; }
body::before { content: ""; position: absolute; z-index: -1; inset: 0 0 auto; height: 760px; background: radial-gradient(ellipse at 76% 0%, #211628 0%, transparent 68%); }
a { color: inherit; text-decoration: none; }
button, select { font: inherit; }
button { cursor: pointer; }
h1, h2, h3, p, figure { margin: 0; }
svg { display: block; }
:focus-visible { outline: 2px solid var(--peach); outline-offset: 5px; }
[id] { scroll-margin-top: 30px; }
.wrap { width: min(1160px, calc(100% - 72px)); margin-inline: auto; }
.mono, .eyebrow { font-family: var(--mono); font-size: .72rem; font-weight: 600; letter-spacing: .13em; text-transform: uppercase; }
.eyebrow { display: flex; align-items: center; gap: 12px; color: var(--peach); }
.eyebrow::before { content: ""; width: 22px; height: 1px; background: currentColor; }
.dim { color: var(--muted); }
.skip { position: absolute; left: 12px; top: 12px; z-index: 5; transform: translateY(-180%); background: var(--peach); color: #251722; padding: 8px 14px; }
.skip:focus { transform: none; }

.top { min-height: 84px; display: grid; grid-template-columns: 1fr auto 1fr; gap: 24px; align-items: center; }
.brand { display: inline-flex; align-items: center; gap: 10px; justify-self: start; width: fit-content; }
.mark { display: grid; place-items: center; width: 37px; height: 37px; border: 1px solid #6b4c58; border-radius: 11px; color: var(--peach); background: #231925; }
.brand-name { font-size: .87rem; font-weight: 800; letter-spacing: .21em; white-space: nowrap; }
.top nav { display: flex; gap: 34px; align-items: center; color: var(--muted); font-size: .86rem; }
.top nav a:hover, .text-link:hover, footer a:hover { color: var(--peach); }
.button { display: inline-flex; justify-content: center; align-items: center; gap: 16px; min-height: 47px; padding: 0 18px; border: 1px solid #554354; border-radius: 8px; background: transparent; color: var(--ink); font-size: .86rem; font-weight: 700; white-space: nowrap; transition: background .18s, border-color .18s, color .18s; }
.button:hover { background: #302336; border-color: var(--peach); }
.button.solid { background: var(--peach); color: #281923; border-color: var(--peach); }
.button.solid:hover { background: #ffd0b9; border-color: #ffd0b9; }
.top > .button { justify-self: end; min-height: 38px; }
.arrow { font-size: 1.1em; }

.hero { isolation: isolate; position: relative; overflow: hidden; min-height: 552px; display: flex; align-items: center; border: 1px solid #493348; border-radius: var(--radius); background: #1b1223; }
.hero-art, .hero-shade { position: absolute; inset: 0; width: 100%; height: 100%; z-index: -2; }
.hero-shade { z-index: -1; background: linear-gradient(90deg, #180f20 0%, #180f20ec 23%, #180f20a2 40%, transparent 65%), linear-gradient(0deg, #170e1de8, transparent 24%); }
.hero-copy { padding: 38px 0 69px; margin-left: clamp(30px, 4.4vw, 62px); }
.hero h1 { font-size: clamp(4.1rem, 7.15vw, 6.2rem); font-weight: 760; letter-spacing: -.083em; line-height: .93; margin: 22px 0 23px; }
.hero h1 em { display: block; color: #ffc0a6; font: italic 400 1.02em/.98 Georgia, serif; letter-spacing: -.075em; }
.hero-copy p { max-width: 340px; color: #e2cfdb; font-size: .98rem; }
.hero-actions { display: flex; gap: 19px; flex-wrap: wrap; align-items: center; margin-top: 27px; }
.text-link { font-size: .84rem; font-weight: 650; }
.art-index { position: absolute; right: 24px; top: 24px; display: flex; gap: 9px; align-items: center; color: #f3c6cd; }
.art-index::before { content: "✦"; color: var(--peach); font-size: .9rem; }
.route { position: absolute; bottom: 20px; right: 24px; left: 24px; display: flex; align-items: center; justify-content: space-between; gap: 16px; color: #e8d0df; }
.route-path { display: flex; align-items: center; gap: 12px; }
.route-path i { width: clamp(30px, 7vw, 88px); border-top: 1px dashed #ce8da2; position: relative; }
.route-path i::before, .route-path i::after { content: ""; position: absolute; top: -3px; width: 5px; height: 5px; border-radius: 50%; background: var(--peach); }
.route-path i::before { left: 0; } .route-path i::after { right: 0; }

.features { display: grid; grid-template-columns: repeat(3, 1fr); padding: 30px 0; border-bottom: 1px solid var(--line); }
.feature { display: grid; grid-template-columns: 44px 1fr; align-items: start; gap: 15px; padding: 0 25px; }
.feature:first-child { padding-left: 0; }
.feature:last-child { padding-right: 0; }
.feature + .feature { border-left: 1px solid var(--line); }
.feature-icon { display: grid; place-items: center; width: 44px; height: 44px; border-radius: 11px; color: var(--peach); background: #221828; border: 1px solid #412c43; }
.feature h3 { font-size: .97rem; margin: 0 0 3px; }
.feature p { color: var(--muted); font-size: .85rem; line-height: 1.5; max-width: 260px; }

.section { margin-top: 84px; }
.section-head { display: flex; align-items: end; justify-content: space-between; gap: 20px 40px; margin-bottom: 24px; }
.section-head h2 { font-size: clamp(2.1rem, 4.4vw, 3.6rem); letter-spacing: -.067em; line-height: 1.04; margin-top: 9px; }
.section-head > p { max-width: 315px; font-size: .92rem; color: var(--muted); }
.schedule { overflow: hidden; border: 1px solid var(--line); border-radius: var(--radius); background: #15121d; }
table { width: 100%; border-collapse: collapse; text-align: left; }
th, td { padding: 15px 24px; }
thead { background: #211a2a; color: #ddcde1; }
thead th { font: 600 .69rem/1.45 var(--mono); letter-spacing: .08em; text-transform: uppercase; }
tbody tr { border-top: 1px solid var(--line); }
tbody tr:hover { background: #1e1626; }
tbody th { font: 600 .77rem/1.3 var(--mono); letter-spacing: .08em; color: var(--peach); white-space: nowrap; }
td { font-weight: 660; font-variant-numeric: tabular-nums; white-space: nowrap; }
td:last-child { text-align: right; }
.next { color: var(--muted); font: .66rem var(--mono); margin-left: 5px; }
.choose { background: transparent; border: 0; padding: 5px 0 5px 5px; color: #ebc3d2; font-size: .81rem; font-weight: 650; }
.choose:hover { color: var(--peach); text-decoration: underline; }
.schedule-note { margin-top: 10px; color: var(--muted); font-size: .78rem; }

.fares { display: grid; grid-template-columns: repeat(3, 1fr); gap: 15px; }
.fare { display: flex; flex-direction: column; position: relative; padding: 23px; border: 1px solid var(--line); border-radius: var(--radius); background: #191522; }
.fare.featured { border-color: #b47580; background: radial-gradient(ellipse at 100% 0%, #48273e, transparent 75%), #211725; }
.fare-top { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 5px 8px; min-height: 24px; color: var(--peach); }
.tag { border: 1px solid #a9697b; padding: 2px 8px; border-radius: 20px; color: #ffd8c9; font: 600 .65rem/1.5 var(--mono); }
.fare h3 { font-size: 1.55rem; letter-spacing: -.045em; margin-top: 8px; }
.price { display: flex; align-items: baseline; gap: 8px; margin: 8px 0 12px; }
.price strong { font-size: 2.45rem; letter-spacing: -.07em; line-height: 1; }
.price span { font-size: .78rem; color: var(--muted); }
.fare ul { list-style: none; padding: 13px 0 0; margin: 0 0 21px; border-top: 1px solid #453348; color: #dfd3e0; font-size: .86rem; }
.fare li { display: flex; gap: 9px; align-items: baseline; margin-top: 6px; }
.fare li::before { content: ""; width: 4px; height: 4px; flex: 0 0 4px; transform: translateY(-2px) rotate(45deg); background: var(--peach); }
.fare .button { margin-top: auto; width: 100%; justify-content: space-between; }

.quote { position: relative; isolation: isolate; overflow: hidden; margin: 72px 0 58px; padding: 37px clamp(24px, 5vw, 65px); background: linear-gradient(110deg, #281b2c, #1e1626 66%, #3b2033); border: 1px solid #49334a; border-radius: var(--radius); }
.quote blockquote { max-width: 720px; margin: 12px 0 15px; color: #fae3dd; font: italic clamp(1.65rem, 3.5vw, 2.7rem)/1.18 Georgia, serif; letter-spacing: -.035em; }
.quote figcaption { color: #d8c3d6; font-size: .81rem; }
.quote-art { position: absolute; right: -32px; top: 50%; transform: translateY(-50%); z-index: -1; width: 330px; color: #bb718b; opacity: .46; }
footer { border-top: 1px solid var(--line); }
.footer-inner { display: flex; align-items: center; justify-content: space-between; gap: 18px; min-height: 91px; }
.footer-inner p { color: var(--muted); font-size: .78rem; }

dialog { width: min(440px, calc(100% - 32px)); max-height: calc(100% - 32px); padding: 27px; border: 1px solid #79536b; border-radius: var(--radius); color: var(--ink); background: #211827; box-shadow: 0 20px 100px #0009; }
dialog::backdrop { background: #0d0914bf; }
.dialog-top { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.close { min-width: 38px; min-height: 36px; padding: 0 8px; font-size: 1.2rem; }
dialog h2 { margin: 9px 0 4px; font-size: 1.75rem; letter-spacing: -.04em; }
dialog p, dialog label { font-size: .88rem; }
dialog label { display: block; margin: 18px 0 6px; }
dialog select { width: 100%; padding: 10px; border: 1px solid #79536b; border-radius: 7px; background: #15111c; color: var(--ink); }
dialog form .solid { margin-top: 17px; width: 100%; }
#trip-result { margin-top: 16px; color: var(--peach); }

@media (max-width: 900px) {
  .wrap { width: calc(100% - 44px); }
  .hero { min-height: 500px; }
  .top nav { gap: 22px; }
  .feature { padding-inline: 14px; gap: 10px; }
  .fare { padding: 17px; }
}
@media (max-width: 660px) {
  .wrap { width: calc(100% - 32px); }
  .top { grid-template-columns: 1fr auto; gap: 10px; padding: 13px 0 14px; }
  .top nav { grid-row: 2; grid-column: 1 / -1; justify-content: space-between; padding-top: 9px; border-top: 1px solid var(--line); }
  .top > .button { grid-column: 2; grid-row: 1; }
  .hero { display: block; min-height: 0; }
  .hero-copy { margin-left: 0; padding: 35px 19px 228px; }
  .hero h1 { font-size: clamp(3.35rem, 11vw, 5rem); margin: 16px 0; }
  .hero-copy p { font-size: .91rem; }
  .hero-actions { margin-top: 19px; gap: 9px 14px; }
  .hero-art { top: auto; height: 319px; }
  .hero-shade { background: linear-gradient(180deg, #180f20 0%, #180f20 40%, #180f20e0 48%, transparent 69%), linear-gradient(0deg, #170e1deb, transparent 21%); }
  .art-index, .route > span { display: none; }
  .route { left: 19px; bottom: 15px; }
  .features { grid-template-columns: 1fr; padding: 7px 0; }
  .feature, .feature:first-child, .feature:last-child { padding: 14px 0; }
  .feature + .feature { border-left: 0; border-top: 1px solid var(--line); }
  .feature p { max-width: none; }
  .section { margin-top: 54px; }
  .section-head { flex-direction: column; align-items: start; gap: 12px; margin-bottom: 17px; }
  th, td { padding: 11px 8px; }
  th:first-child { padding-left: 11px; }
  td:last-child { padding-right: 11px; }
  thead th { font-size: .61rem; }
  tbody td { font-size: .87rem; }
  .next { display: block; margin: 0; }
  .choose { font-size: .75rem; }
  .fares { grid-template-columns: 1fr; gap: 11px; }
  .fare { padding: 20px; }
  .quote { margin: 48px 0 40px; }
  .quote-art { opacity: .22; }
  .footer-inner { align-items: start; flex-direction: column; gap: 12px; padding-block: 20px; }
}
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { transition: none !important; }
}
</style>
