<script>
(() => {
  const dialog = document.querySelector('#trip-dialog');
  const departure = document.querySelector('#departure');
  const fareNote = document.querySelector('#fare-note');
  const result = document.querySelector('#trip-result');
  const times = ['19:40', '20:50', '22:10', '23:30'];
  const arrivals = ['01:10', '02:20', '03:40', '05:00'];
  let fare, price, opener;

  function setDeparture(value) {
    departure.value = value;
    fareNote.textContent = `Selected: DL 0${Number(value) + 1} at ${times[value]}. Fares are one-way per traveler.`;
  }

  document.querySelectorAll('[data-trip]').forEach(link => {
    link.addEventListener('click', () => setDeparture(link.dataset.trip));
  });

  document.querySelectorAll('.book').forEach(button => {
    button.addEventListener('click', () => {
      opener = button;
      ({ fare, price } = button.dataset);
      document.querySelector('#trip-fare').textContent = `${fare} · $${price} per traveler`;
      result.hidden = true;
      dialog.showModal();
      departure.focus();
    });
  });

  departure.addEventListener('change', () => {
    setDeparture(departure.value);
    result.hidden = true;
  });

  document.querySelector('#close-dialog').addEventListener('click', () => dialog.close());
  dialog.addEventListener('close', () => opener?.focus());
  document.querySelector('#trip-form').addEventListener('submit', event => {
    event.preventDefault();
    const i = Number(departure.value);
    setDeparture(i);
    result.hidden = false;
    result.textContent = `${fare} on DL 0${i + 1}: leave Sundown at ${times[i]} and arrive at Vesper at ${arrivals[i]} the next day. One-way fare: $${price}. This is a preview only; no ticket has been booked.`;
  });
})();
</script>
